    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // VALUES YOU CAN PLAY AROUND WITH
    float iter = 100.0f;

    // code
    vec2 mousepos = vec2(lerp(iMouse[0]/iResolution[0], -2.2f, 1.0f), 
                         lerp(iMouse[1]/iResolution[1], -1.0f, 1.0f));

    // this could be improved
    // the mandelbrot set is recalculated every frame even though
    // it really only needs to be calculated once
    // I'm rather new to glsl, so I'm not sure how that can be done
    vec3 mcolor = calcMandelbrot(fragCoord, iter);
    vec3 jcolor = calcJulia(fragCoord, mousepos, iter);

    vec3 color = (mcolor + jcolor) / vec3(2.0f, 2.0f, 2.0f);

    fragColor = vec4(color, 1.0);
}
